    "answer_tr": "اوچ كوروش واردر: ١- جمهورِ علما ٢- نَظَّام ٣- جاحظ\n١- جمهورِ علمايه كوره: خبرك صدقى، واقعه مطابق اولماسیدر.\nكذبى، اولمامسيدر.\n٢- نَظَّامه كوره: خبرك صدقى، خطا اولسە بیلە مُخبِرك اعتقادينه مطابق اولماسیدر. كذبى، اولمامسيدر.\nبو یاكلش كوروشینە \" اِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ \" آيت كريمەسنى دليل كتيرمشدر.\n٣- جاحظه كوره: خبرك صدقى، هم واقعه هم ده اعتقادە مطابق اولماسیدر. كذبى، اولمامسيدر.\nبونلرك غيريسى صادق ده كاذب ده دكلدر.\nبو یاكلش كوروشینە \" اَفْتَرَى عَلَى اللّهِ كَذِبًا اَمْ بِه جِنَّةٌ \" آيت كريمەسنى دليل كتيرمشدر.",
