    "answer_tr": "مخاطبك اوچ حالى واردر: ١- اِبتدائى : اكر مخاطبك ذهنى، حكمدن و حكمده كى تردُّددن خالى اولورسه؛\nتأكیدە احتیاج يوقدر.\n٢- طلبى: اكر مخاطب، حكمى طلب ايديجى اولديغى حالده حكمده تردد ايدرسه، بر تأكيد ايله تأكيدلمك كوزل اولور.\n3- اِنكارى : اكر مخاطب، حكمى انكار ايدرسه، مخاطبك انكارى حسبی ایلە تأكيدلمك واجبدر.\nمثلا: عیسی علیە السلامك حواریلرندن حكايةً، برنجى دفعه يالانلاندقلرنده، \"اِنَّا اِلَيْكُمْ مُرْسَلُونَ\"،\nايكنجى دفعه يالانلاندقلرنده، \"اِنَّا اِلَيْكُمْ لَمُرْسَلُونَ\" قولِ شريفى كبى.",
