    "answer_id": "Pembagian مخاطبك قاچ حالى واردر؟ كلام ناصل ايراد ايديلير؟ menurut kaidah Talkhis al-Miftah adalah: مخاطبك اوچ حالى واردر: ١- اِبتدائى : اكر مخاطبك ذهنى، حكمدن و حكمده كى تردُّددن خالى اولورسه؛ تأكیدە احتیاج يوقدر. ٢- طلبى: اكر مخاطب، حكمى طلب ايديجى اولديغى حالده حكمده تردد ايدرسه، بر تأكيد ايله تأكيدلمك كوزل اولور. 3- اِنكارى : اكر مخاطب، حكمى انكار ايدرسه، مخاطبك انكارى حسبی ایلە تأكيدلمك واجبدر. مثلا: عیسی علیە السلامك حواریلرندن حكايةً، برنجى دفعه يالانلاندقلرنده، \"اِنَّا اِلَيْكُمْ مُرْسَلُونَ\"، ايكنجى دفعه يالانلاندقلرنده، \"اِنَّا اِلَيْكُمْ لَمُرْسَلُونَ\" قولِ شريفى كبى.",
