    "question_tr": "٢٦- \"حقيقتِ عقليه\"نك تعريفى و قسملرى نەلردر؟",
    "answer_tr": "حقيقتِ عقليه : وَهِىَ اِسْنَادُ الْفِعْلِ اَوْ مَعْنَاهُ اِلىَ مَا هُوَ لَهُ عِنْدَ الْمُتَكَلِّمِ فىِ الظَّاهِرِ\nمعناسى: متكلمك ظاهرى حالنە كورە فعل ویا معنا فعلك ما هو لهنە اسناد ایتمەسیدر.\nدورت قسمدر: 1- هم واقعه هم ده اعتقاده مطابق اولور.\nمثالى: مؤمن بر كيمسه نك \"اَنْبَتَ اللَّهُ الْبَقْلَ\" قولى كبى.\n٢- یالكز اعتقاده مطابق اولور.\nمثالى: كافر بر كيمسه نك \"اَنْبَتَ الرَّبِيعُ الْبَقْلَ\" قولى كبى.\n٣- یالكز واقعه مطابق اولور.\nمثالى:معتزلەدن اولمە حالی بیلینمەین كيمسەنك\"خَلَقَ اللَّهُ اْلاَفْعَالَ كُلَّهَا\" قولى كبى.\n٤- هم واقعه هم ده اعتقاده مخالف اولور.\nمثالى: زيدك كلمەديكنى بيلن بر كيمسه نك \"جَاءَ زَيْدٌ\" قولى كبى.",
    "question_id": "Apa definisi balaghah dari ن?",
