    "answer_tr": "دورت قسمدر:١- هم مسند هم ده مسند اليه، حقيقت اولور. مثالى: \"اَنْبَتَ الرَّبِيعُ الْبَقْلَ\" كبى.\n٢- هم مسند هم ده مسند اليه، مجاز اولور. مثالى: \"اَحْيَى اْلاَرْضَ شَبَابُ الزَّمَانِ\" كبى.\n٣- مسند حقيقت، مسند اليه مجاز اولور. مثالى: \"اَنْبَتَ الْبَقْلَ شَبَابُ الزَّمَانِ\" كبى.\n٤- مسند مجاز، مسند اليه حقيقت اولور.\nمثالى: \"اَحْيَى اْلاَرْضَ الرَّبِيعُ\" كبى.",
