    "question_tr": "٣١- قرآنِ كريمده مجازِ عقلى وارميدر؟ بر مثال ويريكز؟",
    "answer_tr": "قرآن كريمده مجازِ عقلى واردر و چوقدر:\n\"وَ اِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ اِيمَانًا\" محل استشهاد : بو آيت كريمەده \"زَادَتْ\" فعلنك، ما هو لهنك غیريسى اولان \"آيَاتُهُ\"یە اسنادی مجازدر.\n\"يُذَبِّحُ اَبْنَائَهُمْ\" محل استشهاد : بو آيت كريمەده \"يُذَبِّحُ\" فعلنك، ما هو لهنك غیريسى اولان \"فِرْعَوْن\"ە اسنادی مجازدر.\n\"يَنْزِعُ عَنْهُمَا لِبَاسَهُمَا\" محل استشهاد :بو آيت كريمەده \"يَنْزِعُ\" فعلنك، ما هو لهنك غیريسى اولان \"ابليس\"ە اسنادی مجازدر.\n\"يَوْماً يَجْعَلُ الْوِلْدَانَ شِيبًا\" محل استشهاد :بو آيت كريمەده \"يَجْعَلُ\" فعلنك، ما هو لهنك غیريسى اولان \"یوم\"ە اسنادی مجازدر.\n\"وَ اَخْرَجَتِ الْاَرْضُ اَثْقَالَهَا\" محل استشهاد :بو آيت كريمەده \"اَخْرَجَتْ\" فعلنك، ما هو لهنك غیريسى اولان \"اَرْض\"ە اسنادی مجازدر.\n\"يَا هَامَانُ ابْنِ لىِ صَرْحاً\" محل استشهاد :بو آيت كريمەده \"اِبْنِ\" فعلنك، ما هو لهنك غیريسى اولان \"هَامَانْ\"ە اسنادی مجازدر.\n(يَا هَامَانُ ابْنِ لىِ صَرْحاً آیت كریمەسی مجازِ عقلينك، انشائى كلامدە دە اولديغنه مثالدر.)",
