    "answer_tr": "١- ذكری زیادە مُهِم اولدیغی ایچون، بو ده؛\nمسند الیهك تقدیمی اصل اولوب اصلدن دونمەیی ایجاب ایدن بر سبب اولمادیغی ایچون،\nمبتدا دە خبرە تشویق اولدیغندن دولايی، مخاطبك ذهنندە خبری قرارلاشدیرمق ایچون،\nمثلا: \"وَالَّذِی حَارَتِ اْلبَرِیَّةُ فِیەِ - حَیَوَانٌ مُسْتَحْدَثٌ مِنْ جَمَادٍ\" شعرى كبی.\nنكتە: خبرە تشویق و مخاطبك ذهنندە قرارلاشدیرمق ایچون، مسند الیە اولان \"اَلَّذِی\" لفظی، تقدیم اولونمشدر.\n٢- سوينچلی خبری عجلە ایتدیرمك ایچون، (خيره يورمق ایچون)\n٣- كوتو خبری عجلە ایتدیرمك ایچون، (شره يورمق ایچون)\n٤- خاطرندن چيقماياجغنی اشارت ایچون،\n٥- لذّت دویمق ایچون،",
