    "answer_tr": "١- بدیع بر حكمە مخصوص اولديغندن، مسند الیهی تمییز ایتمه يي قصد ايتمك (كمالِ عنايت) ایچون،\nمثلا: \" كَمْ عَاقِلٍ عَاقِلٍ اَعْيَتْ مَذَاهِبُهُ - وَجَاهِلٍ جَاهِلٍ تَلْقَاهُ مَرْزُوقًا - هَذَا الَّذِى تَرَكَ اْلاَوْهَامَ حَائِرَةً - وَصَيَّرَ الْعَالِمَ النِّحْريِرَ زِنْديِقًا\" شعرى كبی.\nنكتە: بدیع بر حكمە مخصوص اولديغندن، مسند الیهی تمییز ایتمه يي قصد ايتمك (كمالِ عنايت) ایچون، ضمیر یرینە \"هذا\" دييه اسم اشارت كتیریلمشدر.\n٢- مخاطب ایلە آلای ایتمك (تهكُّم) ایچون،\n٣-كمالِ بَلادت (مخاطبك احمق اولدیغنی) تنبیە ایچون،\n٤- كمالِ فَطانت (مخاطبك ذكی اولدیغنی) تنبیە ایچون،\n٥- كمالِ ظهور (مسند الیهك تام ظاهر اولديغنی) اِدِّعا ایچون،",
