    "question_tr": "68- ﴿ قُلْ هُوَ اللَّهُ اَحَدٌ اَللەُ الصَّمدُ ﴾ ، ﴿ وَ بِالْحَقِّ اَنْزَلْنَاهُ وَ بِالْحَقِّ نَزَلَ ﴾ ، ﴿ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللهِ ﴾ و (اِلَهىِ عَبْدُكَ الْعَاصِى اَتَاكَا) مثاللرینك نكتەلرندن بر طانەسنی سویلەیكز؟",
    "answer_tr": "\"قُلْ هُوَ اللَّهُ اَحَدٌ اَللەُ الصَّمدُ\"\nمحل استشهاد : مقتضای ظاهر \"هُوَ الصَّمدُ\" ایدی، زیادە تمكين (تقرير) ایچون، ضمیر یرینە اسم ظاهر اولان \" اَللەُ \" لفظی كتیریلمشدر.\n\"وَ بِالْحَقِّ اَنْزَلْنَاهُ وَ بِالْحَقِّ نَزَلَ\"\nمحل استشهاد : مقتضای ظاهر \"وَ بِهِ نَزَلَ\" ایدی، مسند اليهك غيريسنده زیادە تقرير ایچون، ضمیر یرینە اسم ظاهر اولان \"بِالْحَقِّ\" لفظی كتيريلمشدر.\n\"فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللهِ\"\nمحل استشهاد : مقتضای ظاهر \"فَتَوَكَّلْ عَلَیَّ\" ایدی، مسند اليهك غيريسنده، امر ایدیلن شيئە دعوت ايدنی تقویە ایچون، ضمیر یرینە اسم ظاهر اولان \"عَلَی اللەِ\"لفظهء جلالی كتيريلمشدر.\n\"اِلَهىِ عَبْدُكَ الْعَاصِى اَتَاكَا - مُقِرًّا بِالذُّنُوبِ وَقَدْ دَعَاكَا\"\nنكتە: مقتضای ظاهر \"اَنَا الْعَاصِی\" ایدی، رحمت و مرحمت طلب ایتمك ایچون، ضمیر یرینە اسم ظاهر اولان \"عَبْدُكَ\" كتيريلمشدر.",
    "question_id": "Jelaskan faidah rahasia balaghah (nuktah) pada: ﴿ قُلْ هُوَ اللَّهُ اَحَدٌ اَللەُ الصَّمدُ ﴾ ، ﴿ وَ بِالْحَقِّ اَنْزَلْنَاهُ وَ بِالْحَقِّ نَزَلَ ﴾ ، ﴿ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللهِ ﴾ و (اِلَهىِ عَبْدُكَ الْعَاصِى اَتَاكَا) مثاللرینك نكتەلرندن بر طانەسنی سویلەیكز؟",
    "answer_id": "Nuktah dan rahasia balaghahnya adalah: \"قُلْ هُوَ اللَّهُ اَحَدٌ اَللەُ الصَّمدُ\" محل استشهاد : مقتضای ظاهر \"هُوَ الصَّمدُ\" ایدی، زیادە تمكين (تقرير) ایچون، ضمیر یرینە اسم ظاهر اولان \" اَللەُ \" لفظی كتیریلمشدر. \"وَ بِالْحَقِّ اَنْزَلْنَاهُ وَ بِالْحَقِّ نَزَلَ\" محل استشهاد : مقتضای ظاهر \"وَ بِهِ نَزَلَ\" ایدی، مسند اليهك غيريسنده زیادە تقرير ایچون، ضمیر یرینە اسم ظاهر اولان \"بِالْحَقِّ\" لفظی كتيريلمشدر. \"فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللهِ\" محل استشهاد : مقتضای ظاهر \"فَتَوَكَّلْ عَلَیَّ\" ایدی، مسند اليهك غيريسنده، امر ایدیلن شيئە دعوت ايدنی تقویە ایچون، ضمیر یرینە اسم ظاهر اولان \"عَلَی اللەِ\"لفظهء جلالی كتيريلمشدر. \"اِلَهىِ عَبْدُكَ الْعَاصِى اَتَاكَا - مُقِرًّا بِالذُّنُوبِ وَقَدْ دَعَاكَا\" نكتە: مقتضای ظاهر \"اَنَا الْعَاصِی\" ایدی، رحمت و مرحمت طلب ایتمك ایچون، ضمیر یرینە اسم ظاهر اولان \"عَبْدُكَ\" كتيريلمشدر.",
