    "originalNumber": 71,
    "question_tr": "70- التفات قاچ شكلده اولور صایكز و بریسنك مثالینی سویلەیكز؟",
    "answer_tr": "التفات آلتى (٦) شكلده اولور:\n١- متكلمدن مخاطبه التفات،\nمثلا: \"وَ مَا لِىَ لَا اَعْبُدُ الَّذِى فَطَرَنىِ وَ اِلَيْهِ تُرْجَعُونَ\" آيت كريمەسى كبى.\nمحل استشهاد :\"لِىَ\" اولان متكلمدن، \"تُرْجَعُونَ\" اولان مخاطبه التفات واردر.\n٢- متكلمدن غائبه التفات،\nمثلا: \"اِنَّا اَعْطَيْنَاكَ الْكَوْثَرَ – فَصَلِّ لِرَبِّكَ وَانْحَرْ\" آيت كريمەسى كبى.\nمحل استشهاد : \"اِنَّا اَعْطَيْنَا\" اولان متكلمدن، \"لِرَبِّكَ\" اولان غائبه التفات واردر.\n٣- مخاطبدن متكلمه التفات،\nمثلا: \"طَحَا بِكَ قَلْبٌ فىِ الْحِسَانِ طَرُوبٌ–بُعَيْدَ الشَّبَابِ عَصْرَحَانَ مَشِيبُ يُكَلِّفُنِى لَيْلَى وَ قَدْ شَطَّ وَلْيُهَا–وَ عَادَتْ عَوَادٍ بَيْنَنَا وَ خُطُوبٌ\"شعرى كبى.\nنكته: \"بِكَ\" اولان مخاطبدن، \"يُكَلِّفُنِى\" اولان متكلمه التفات واردر.\n٤- مخاطبدن غائبه التفات،\nمثلا: \"حَتَّى اِذَا كُنْتُمْ فىِ الْفُلْكِ وَ جَرَيْنَ بِهِمْ\" آيت كريمەسى كبى.\nمحل استشهاد : \"اِذَا كُنْتُمْ\" اولان مخاطبدن، \"بِهِمْ\" اولان غائبه التفات واردر.\n٥- غائبدن متكلمه التفات،\nمثلا: \"اَللَّهُ الَّذِى اَرْسَلَ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَسُقْنَاهُ\" آيت كريمەسى كبى.\nمحل استشهاد : \"اَرْسَلَ\" اولان غائبدن، \"فَسُقْنَاهُ\" اولان متكلمه التفات واردر.\n٦- غائبدن مخاطبه الفات،\nمثلا:\" مَالِكِ يَوْمِ الدِّينِ – اِيَّاكَ نَعْبُدُ وَ اِيَّاكَ نَسْتَعِينُ\" آيت كريمەسى كبى.\nمحل استشهاد : \"مَالِكِ يَوْمِ الدِّينِ\" اولان غائبدن، \"اِيَّاكَ\" اولان مخاطبه التفات واردر.",
    "question_id": "Ada berapa pembagian dan macam dari التفات قاچ شكلده اولور صایكز و بریسنك مثالینی سویلەیكز؟?",
    "answer_id": "Pembagian التفات قاچ شكلده اولور صایكز و بریسنك مثالینی سویلەیكز؟ menurut kaidah Talkhis al-Miftah adalah: التفات آلتى (٦) شكلده اولور: ١- متكلمدن مخاطبه التفات، مثلا: \"وَ مَا لِىَ لَا اَعْبُدُ الَّذِى فَطَرَنىِ وَ اِلَيْهِ تُرْجَعُونَ\" آيت كريمەسى كبى. محل استشهاد :\"لِىَ\" اولان متكلمدن، \"تُرْجَعُونَ\" اولان مخاطبه التفات واردر. ٢- متكلمدن غائبه التفات، مثلا: \"اِنَّا اَعْطَيْنَاكَ الْكَوْثَرَ – فَصَلِّ لِرَبِّكَ وَانْحَرْ\" آيت كريمەسى كبى. محل استشهاد : \"اِنَّا اَعْطَيْنَا\" اولان متكلمدن، \"لِرَبِّكَ\" اولان غائبه التفات واردر. ٣- مخاطبدن متكلمه التفات، مثلا: \"طَحَا بِكَ قَلْبٌ فىِ الْحِسَانِ طَرُوبٌ–بُعَيْدَ الشَّبَابِ عَصْرَحَانَ مَشِيبُ يُكَلِّفُنِى لَيْلَى وَ قَدْ شَطَّ وَلْيُهَا–وَ عَادَتْ عَوَادٍ بَيْنَنَا وَ خُطُوبٌ\"شعرى كبى. نكته: \"بِكَ\" اولان مخاطبدن، \"يُكَلِّفُنِى\" اولان متكلمه التفات واردر. ٤- مخاطبدن غائبه التفات، مثلا: \"حَتَّى اِذَا كُنْتُمْ فىِ الْفُلْكِ وَ جَرَيْنَ بِهِمْ\" آيت كريمەسى كبى. محل استشهاد : \"اِذَا كُنْتُمْ\" اولان مخاطبدن، \"بِهِمْ\" اولان غائبه التفات واردر. ٥- غائبدن متكلمه التفات، مثلا: \"اَللَّهُ الَّذِى اَرْسَلَ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَسُقْنَاهُ\" آيت كريمەسى كبى. محل استشهاد : \"اَرْسَلَ\" اولان غائبدن، \"فَسُقْنَاهُ\" اولان متكلمه التفات واردر. ٦- غائبدن مخاطبه الفات، مثلا:\" مَالِكِ يَوْمِ الدِّينِ – اِيَّاكَ نَعْبُدُ وَ اِيَّاكَ نَسْتَعِينُ\" آيت كريمەسى كبى. محل استشهاد : \"مَالِكِ يَوْمِ الدِّينِ\" اولان غائبدن، \"اِيَّاكَ\" اولان مخاطبه التفات واردر.",
