    "question_tr": "72- ﴿ وَيَوْمَ يُنْفَخُ فِى الصُّورِ فَفَزِعَ مَنْ فِى السَّمَوَاتِ وَمَنْ فِی الْأَرْضِ ﴾ ، ﴿ وَ اِنَّ الدِّينَ لَوَاقِعٌ ﴾، ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ ﴾ آیت كریمەلرندن بر طانەسنی سویلەیكز؟",
    "answer_tr": "\"وَيَوْمَ يُنْفَخُ فِى الصُّورِ فَفَزِعَ مَنْ فِى السَّمَوَاتِ وَمَنْ فِی الْأَرْضِ\"\nمحل استشهاد : مقتضای ظاهر \"فَیَفْزَعُ\" ایدی. تحقّقِ وقوعنە تنبيه ايچون، مقتضای ظاهرك خلافنە مضارع مقامندە ماضی كتیریلمشدر.\n\"وَ اِنَّ الدِّينَ لَوَاقِعٌ\"\nمحل استشهاد : مقتضای ظاهر \"لَیَقَعُ\" ایدی. تحقّقِ وقوعنە تنبيه ايچون، مقتضای ظاهرك خلافنە مضارع مقامندە اسم فاعل كتیریلمشدر.\n\"ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ\"\nمحل استشهاد : مقتضای ظاهر \"یُجْمَعُ\" ایدی. تحقّقِ وقوعنە تنبيه ايچون، مقتضای ظاهرك خلافنە مضارع مقامندە اسم مفعول كتیریلمشدر.",
