    "question_tr": "74- قلب قاچ قسمدر و بر طانەسنك مثالنی ایضاح ایدیكز.",
    "answer_tr": "قلب، ايكی قسمدر؛\n١- قلبِ مقبول؛ لطيف بر معنا افاده ايتمەسیدر.\nمثلا: \"وَ مَهْمَهٍ مُغْبَرَّةٍ اَرْجَائُهُ – كَأَنَّ لَوْنَ اَرْضِهِ سَمَائُهُ\" شعرى كبى.\nنكته: \"ارض\" و \"سما\" كلمەلرى ير دكيشديرمكله قلب ميدانه كلمش و بو قلب لطيف بر معنا (مبالغه) افاده ايتديكى ايچون مقبولدر.\n٢- قلبِ مردود؛ لطيف بر معنا افاده ايتمەمەسیدر.\nمثلا: \" كَمَا طَيَّنْتَ بِالْفَدَنِ السَّيَاعَا\" شعرى كبى\nنكته: \"فَدَنْ\" و \"سَيَاعَا\" كلمەلرى ير دكيشديرمكله قلب ميدانه كلمش و بو قلب لطيف بر معنا افاده ايتمەديكى ايچون مردوددر.",
