    "answer_id": "Pembagian قلب قاچ قسمدر و بر طانەسنك مثالنی ایضاح ایدیكز. menurut kaidah Talkhis al-Miftah adalah: قلب، ايكی قسمدر؛ ١- قلبِ مقبول؛ لطيف بر معنا افاده ايتمەسیدر. مثلا: \"وَ مَهْمَهٍ مُغْبَرَّةٍ اَرْجَائُهُ – كَأَنَّ لَوْنَ اَرْضِهِ سَمَائُهُ\" شعرى كبى. نكته: \"ارض\" و \"سما\" كلمەلرى ير دكيشديرمكله قلب ميدانه كلمش و بو قلب لطيف بر معنا (مبالغه) افاده ايتديكى ايچون مقبولدر. ٢- قلبِ مردود؛ لطيف بر معنا افاده ايتمەمەسیدر. مثلا: \" كَمَا طَيَّنْتَ بِالْفَدَنِ السَّيَاعَا\" شعرى كبى نكته: \"فَدَنْ\" و \"سَيَاعَا\" كلمەلرى ير دكيشديرمكله قلب ميدانه كلمش و بو قلب لطيف بر معنا افاده ايتمەديكى ايچون مردوددر.",
