    "answer_tr": "\"اِنَّ مَحَلًّا وَ اِنَّ مُرْتَحَلاً\"\nنكته: اختصار ایچون و عقلى دليلە دونولدیكنی دوشوندورمك ایچون، مسند اولان \"لَنَا\" لفظلری، ترك (حذف) ايديلمشدر.\n\"قُلْ لَوْ اَنْتُمْ تَمْلِكُونَ حَزَائِنَ رَحْمَةِ رَبِّی\"\nمحل استشهاد: عبثدن احتراز ايچون، مسند اولان \"تَمْلِكُونَ\" لفظی، ترك (حذف) ايديلمشدر.",
    "question_id": "Jelaskan faidah rahasia balaghah (nuktah) pada: \" اِنَّ مَحَلًّا وَ اِنَّ مُرْتَحَلاً \" شعرینك نكتەسنی و ﴿ قُلْ لَوْ اَنْتُمْ تَمْلِكُونَ حَزَائِنَ رَحْمَةِ رَبِّی ﴾ آیت كریمەسنك محل استشهادنی سویلەیكز.",
