    "answer_tr": "هم مسند و همده مسند اليهك حذف ايديلمه احتمالی اولديغنه مثالدر. شويله كه؛\nاكر \"فَصَبْرٌ جَمِيلٌ اَجْمَلُ\" تقديرنده اولورسە، مسند اولان \"اَجْمَلُ\" لفظى ترك (حذف) ايديلمشدر.\nاكر \"فَاَمْرِى صَبْرٌ جَمِيلٌ\" تقديرنده اولورسە، مسند اليه اولان \"اَمْرِى\" لفظى ترك (حذف) ايديلمشدر.\nنوط: حضرتِ استاذیمز، بو آیت كریمەیی \"فَصَبْرِی جَمِیلٌ\" دییە تقدیر ایتمشلردر.\nيعنی مسند و مسند اليهك غیری اولان مضاف الیە ترك (حذف) ايديلمشدر.",
