    "answer_tr": "مسندك حذفنە دلالت ایدن قرینە، ايكی قسمدر؛\n١- كلام سؤالِ محقَّقە جواب واقع اولماسیدر،\nمثلا: \"وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللهُ\" آيتِ كريمەسى كبی.\nمحل استشهاد: \" مَنْ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ \" سؤالِ محقق قرینەسی ایلە، مسند اولان \"خَلَقَهُنَّ\" ترك (حذف) ايديلمشدر.\n١- كلامك سؤالِ مقدَّره جواب واقع اولماسیدر،\nمثلا: \"لِيُبْكَ يَزيِدُ ضَارِعٌ لِخُصوُمَةٍ\" شعرى كبی.\nنكتە: \"مَنْ یَبْكِیهِ\" سؤالِ مقدَّر قرینەسی ایلە، مسند اولان \"یَبْكِی\" ترك (حذف) ايديلمشدر",
