    "answer_tr": "تغليب : اوزرلرینە بر لفظك اطلاقندە (قوللانیلمەسندە) ایكی معلومدن برینی دیكرینە ترجیح ایتمكدر.\nمثلا: \"وَ كَانَتْ مِنَ الْقَانِتِينَ\" محل استشهاد : مذكر مؤنث اوزرينه تغلیب ایدیلەرك، \"قَانِتَات\" یرندە،\"قَانِتِینَ\" وارد اولمشدر.\nمثلا: \"بَلْ أَنْتُمْ قَوْمٌ تَجْهَلُونَ\" محل استشهاد : معنا طرفی (مخاطب) لفظ طرفی (غائب) اوزرينه تغلیب ایدیلەرك. \"یَجْهَلُونَ\" یرندە،\"تَجْهَلُونَ\" وارد اولمشدر.",
