    "answer_tr": "ايكى قسمدر:\n1- مطلق فعل، متعلِّق (خصوصی بر مفعولە تعلق ایدن) فعلدن كنايه قيلينیر،\nمثلا: \"شَجْوُ حُسَّادِهِ وَ غَيْظُ عِدَاهُ – اَنْ يَرَى مُبْصِرٌ وَ يَسْمَعَ وَاعٍ\" شعرى كبى.\nنكته: متعدی اولان \"يَرَى و يَسْمَعَ\" فعللری لازم منزلەسنە ایندیریلمش اولوب خصوصی بر مفعولە (مَحَاسِنَهُ و اَخْبَارَهُ) تعلق ایدن فعللرندن كنايه قیلنمشدر.\n٢- مطلق فعل، متعلِّق (خصوصی بر مفعولە تعلق ایدن) فعلدن كنايه قيلنماز،\nمثلا: \"قُلْ هَلْ يَسْتَوِى الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لاَ يَعْلَمُونَ\" آيت كريمەسى كبى.\nمحل استشهاد : متعدی اولان \"يَعْلَمُونَ و لاَ يَعْلَمُونَ\" فعللری لازم منزلەسنە ایندیریلمش اولوب خصوصی بر مفعولە تعلق ایدن فعللرندن كنايه قیلنمەمشدر",
