    "question_tr": "92- ﴿ فَلَوْ شَاءَ لَهَدَاكُمْ اَجْمَعِينَ ﴾ ، (وَلَوْ شِئْتُ اَنْ اَبْكِىَ دَمًا لَبَكَيْتُهُ)، (وَلَمْ يُبْقِ مِنِّى الشَّوْقُ غَيْرَ تَفَكُّرىِ - فَلَوْ شِئْتُ اَنْ اَبْكِىَ بَكَيْتُ تَفَكُّرًا)، (وَ كَمْ ذُدْتَ عَنِّى مِنْ تَحَامُلٍ حَادِثٍ – وَ سَوْرَةِ اَيَّامٍ حَزَزْنَ اِلىَ الْعَظْمِ) آیت كریمە ویا مثاللردن بر طانسینی سویلەیكز؟",
    "answer_tr": "\"فَلَوْ شَاءَ لَهَدَاكُمْ اَجْمَعِينَ\"\nمحل استشهاد : مشیَّت فعلنك مفعولی اولان \"هِدَايَتَكُمْ\" ابهامدن صكرە بیان ایچون حذف اولونمشدر.\n\"وَلَوْ شِئْتُ اَنْ اَبْكِىَ دَمًا لَبَكَيْتُهُ\"\nنكتە: مشیَّت فعلنك مفعولنە (قان آغلامەیە) تعلقی غریب اولدیغی ایچون \"اَنْ اَبْكِىَ\" اولان مفعول حذف اولونمامشدر.\n\"وَلَمْ يُبْقِ مِنِّى الشَّوْقُ غَيْرَ تَفَكُّرىِ - فَلَوْ شِئْتُ اَنْ اَبْكِىَ بَكَيْتُ تَفَكُّرًا\"\nنكتە: حذفه قرينه اولماديغى ايچون، مشیَّت فعلنك مفعولی اولان \"اَنْ اَبْكِىَ\" حذف اولونمامشدر.\n\"وَ كَمْ ذُدْتَ عَنِّى مِنْ تَحَامُلٍ حَادِثٍ – وَ سَوْرَةِ اَيَّامٍ حَزَزْنَ اِلىَ الْعَظْمِ\"\nنكته: ابتداءً مراد اولونميان معنانك مراد اولونمە توهُّمنى دفع ايچون \"اَللَّحْمَ\" اولان مفعول حذف اولونمشدر.",
    "question_id": "Berikan contoh dan penjelasan balaghah untuk: ﴿ فَلَوْ شَاءَ لَهَدَاكُمْ اَجْمَعِينَ ﴾ ، (وَلَوْ شِئْتُ اَنْ اَبْكِىَ دَمًا لَبَكَيْتُهُ)، (وَلَمْ يُبْقِ مِنِّى الشَّوْقُ غَيْرَ تَفَكُّرىِ - فَلَوْ شِئْتُ اَنْ اَبْكِىَ بَكَيْتُ تَفَكُّرًا)، (وَ كَمْ ذُدْتَ عَنِّى مِنْ تَحَامُلٍ حَادِثٍ – وَ سَوْرَةِ اَيَّامٍ حَزَزْنَ اِلىَ الْعَظْمِ) آیت كریمە ویا مثاللردن بر طانسینی سویلەیكز؟",
