    "question_tr": "93- ﴿ وَاللَّهُ يَدْعُو اِلىَ دَارِ السَّلاَمِ ﴾ ، (قَدْ طَلَبْنَا فَلَمْ نَجِدْ لَكَ – فىِ السُّودَدِ وَالْمَجْدِ وَالْمَكَارِمِ مِثْلًا)، ﴿ اَرِنىِ اَنْظُرْ اِلَيْكَ ﴾ ، ﴿ مَا وَدَّعَكَ رَبُّكَ وَ مَاقَلَى ﴾ و (مَا رَأَيْتُ مِنْهُ وَ لَا رَأَى مِنِّى) آیت كریمە ویا مثاللردن بر طانسینی سویلەیكز.",
    "answer_tr": "\"قَدْ طَلَبْنَا فَلَمْ نَجِدْ لَكَ – فىِ السُّودَدِ وَالْمَجْدِ وَالْمَكَارِمِ مِثْلًا\"\nنكته: ايكنجى دفعە صراحةً ذكری مراد اولندیغی ایچون، \"مِثْلاً\" اولان برنجی مفعول حذف اولونمشدر.\n\"وَاللَّهُ يَدْعُو اِلىَ دَارِ السَّلاَمِ\" محل استشهاد : اختصار ايله برابر تعميم ايچون، \"جَمِيعَ عِبَادِهِ\" مفعول حذف اولونمشدر.\n\"اَرِنىِ اَنْظُرْ اِلَيْكَ\" محل استشهاد : مجرَّد اختصار ايچون، \"ذَاتَكَ\" اولان مفعول حذف اولونمشدر.\n\"مَا وَدَّعَكَ رَبُّكَ وَ مَاقَلَى\" محل استشهاد : فاصلەيه رعايت ايچون، مفعول اولان منصوب متصل ضمیری \"كَ\" حذف اولونمشدر.\nعائشه والدەمزك \"مَا رَأَيْتُ مِنْهُ وَ لَا رَأَى مِنِّى\"قولی نكته: ذكرى مستهجَن اولديغى ايچون، \"اَلْعَوْرَةَ\" اولان مفعول حذف اولونمشدر.",
