    "answer_tr": "\"ما\" ایلە، بر اسمك ایضاحي ویا مسمَّى نك ماهیتی، \"مَنْ\" ایلە، علم صاحبی ایچون معین اولان شی طلب اولنور.\n\"اَیٌّ\" ایلە، ایكی اورتاقدن برينی دیكرندن آییران شیدن،\nمثلا: \"اَیُّ الْفَرِیقَیْنِ خَیْرٌ مَقَامًا\" آیت كریمەسی كبی\nمحل استشهاد: اَیُّ لفظی ایكی اورتاقدن برینی دیكرندن آییرمق ایچوندر.\n\"كَمْ\" ایلە، عدددن،\nمثلا: \"سَلْ بَنِى اِسْرَائِيلَ كَمْ آتَيْنَاهُمْ مِنْ آيَةٍ بَيِّنَةٍ\" آيت كريمەسى كبی\nمحل استشهاد: كم ایلە عدددن سؤال ایدیلمشدر.",
    "question_id": "Jelaskan persoalan balaghah mengenai: استفهام حرفلرندن \"ما\" -\"اَیٌّ\" و \"كَمْ\" ایلە ندن سؤال اولونور؟",
    "answer_id": "Penjelasan menurut naskah Talkhis al-Miftah: \"ما\" ایلە، بر اسمك ایضاحي ویا مسمَّى نك ماهیتی، \"مَنْ\" ایلە، علم صاحبی ایچون معین اولان شی طلب اولنور. \"اَیٌّ\" ایلە، ایكی اورتاقدن برينی دیكرندن آییران شیدن، مثلا: \"اَیُّ الْفَرِیقَیْنِ خَیْرٌ مَقَامًا\" آیت كریمەسی كبی محل استشهاد: اَیُّ لفظی ایكی اورتاقدن برینی دیكرندن آییرمق ایچوندر. \"كَمْ\" ایلە، عدددن، مثلا: \"سَلْ بَنِى اِسْرَائِيلَ كَمْ آتَيْنَاهُمْ مِنْ آيَةٍ بَيِّنَةٍ\" آيت كريمەسى كبی محل استشهاد: كم ایلە عدددن سؤال ایدیلمشدر.",
