    "answer_tr": "استفهام لفظلرينك استفهامك غيريسنده قوللانيلديغى يرلر؛\n۱- استبطا (آغيردن بولمق - ياواش و آغير بولمق) ايچون،\n۲- تعجُّب ايچون،\n۳- ضلالت اوزره تنبيه ايچون،\n٤- وعيد (تهديد) ايچون،\n٥- تقرير ايچون،\n٦- انكار ايچون،\n۷- تهكم (آلاى) ايچون،\n۸- تحقير ايچون،\n۹- تهويل (قورقوتمق) ايچون،\n۱۰- استبعاد (اوزاق كورمك) ايچون،",
