    "answer_tr": "\"مَا لِىَ لَا اَرَى الْهُدْهُدَ\"\nمحل استشهاد: استفهام حرفی اولان \"ما\" لفظی، تعجب ایچون قوللانیلمشدر.\n\"فَاَيْنَ تَذْهَبُونَ\" محل استشهاد: استفهام حرفی اولان \"این\" لفظی، ضلالت اوزره تنبيه ایچون قوللانیلمشدر.\n\"اَغَيْرَ اللَّهِ تَدْعُونَ\" محل استشهاد: استفهام لفظی اولان همزە، انكار ایچون قوللانیلمشدر.\n\"اَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ\" محل استشهاد: استفهام لفظی اولان همزە، انكار ایچون قوللانیلمشدر.",
