    "answer_tr": "استفهامِ انكارینك قوللانیلدیغی یرلر، ايكی (٢) يردەدر.\n١- توبیخ ایچون؛\nمثلا: \"اَعَصَیْتَ رَبَّكَ\" نكتە: استفهامِ انكاری، ماضيدە توبیخ ایچون قوللانيلمشدر.\nمثلا: \"اَتَعْصِی رَبَّكَ\" نكتە: استفهامِ انكاری، مضارعدە توبیخ ایچون قوللانيلمشدر.\n٢- تكذیب ایچون؛ مثلا: \"اَفَاَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ\" محل استشهاد: استفهامِ انكاری، ماضيدە تكذیب ایچون قوللانيلمشدر.\nمثلا: \"اَنُلْزِمُكُمُوهَا\" محل استشهاد: استفهامِ انكاری، مضارعدە تكذیب ایچون قوللانيلمشدر.",
