    "answer_id": "Pembagian استفهامِ انكارینك قوللانیلدیغی یرلر قاچدر و نەلردر؟ menurut kaidah Talkhis al-Miftah adalah: استفهامِ انكارینك قوللانیلدیغی یرلر، ايكی (٢) يردەدر. ١- توبیخ ایچون؛ مثلا: \"اَعَصَیْتَ رَبَّكَ\" نكتە: استفهامِ انكاری، ماضيدە توبیخ ایچون قوللانيلمشدر. مثلا: \"اَتَعْصِی رَبَّكَ\" نكتە: استفهامِ انكاری، مضارعدە توبیخ ایچون قوللانيلمشدر. ٢- تكذیب ایچون؛ مثلا: \"اَفَاَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ\" محل استشهاد: استفهامِ انكاری، ماضيدە تكذیب ایچون قوللانيلمشدر. مثلا: \"اَنُلْزِمُكُمُوهَا\" محل استشهاد: استفهامِ انكاری، مضارعدە تكذیب ایچون قوللانيلمشدر.",
