    "answer_tr": "جهتِ جامعە: ایكی جملە آراسندە ضدلق ویا تناسب جهتندن بر علاقە اولماسیدر.\n\"وَاِذَا خَلَوْا اِلَى شَيَاطِينِهِمْ قَالُوا اِنَّا مَعَكُمْ اِنَّمَا نَحْنُ مُسْتَهْزِؤُنَ اَللهُ يَسْتَهْزِئُ بِهِمْ\"\nمحل استشهاد: \"اَللهُ يَسْتَهْزِئُ بِهِمْ\" جملەسنك \"اِنَّا مَعَكُمْ\" جملەسنه اعراب حكمنده اورتاقلیغی مراد اولنماديغى ايچون فصل اولمشدر.\n\"لَا وَالَّذِى هُوَ عَالِمٌ اَنَّ النَّوَى صَبِرٌ وَ اَنَّ اَبَا الْحُسَيْنِ كَريِمٌ\"\nنكتە: \"اَنَّ النَّوَى صَبِرٌ\" جملەسی ایلە \"وَ اَنَّ اَبَا الْحُسَيْنِ كَريِمٌ\" جملەسی آراسندە جهتِ جامعە اولمادیغی ایچون وصل یاپیلماسی عیب كورولمشدر.",
