    "question_tr": "123- كمالِ اتصال ندر؟ و بر مثال سویلەیكز.",
    "answer_tr": "ایكینجی جملەنك برنجی جملەدن تأكید، بدل ویا عطف بیان اولماسیدر.\n١- تأكيد اولدیغینە مثال :\"ذَلِكَ اْلكِتَابُ لَا رَيْبَ فىهِ\" آيت كريمەسى كبى.\nمحل استشهاد: \"لَا رَيْبَ فیهِ\" جملەسی \"ذَلِكَ اْلكِتَابُ\" جملەسنی تأكيد ایتمكلە كمال اتصال واقع اولوب فصل اولمشدر.\n٢- بدل اولدیغینە مثال :\"اَمَدَّكُمْ بِمَا تَعْلَمُونَ اَمَدَّكُمْ بِاَنْعَامٍ وَبَنِينَ وَ جَنَّاتٍ وَعُيُونٍ\" آيت كريمەسى كبى.\nمحل استشهاد: \"اَمَدَّكُمْ بِاَنْعَامٍ\" جملەسی \"اَمَدَّكُمْ بِمَا تَعْلَمُونَ\" جملەسندن بدل بعض اولمقلە كمال اتصال اولوب فصل اولمشدر.\nمثال: \"اَقُولُ لَهُ اِرْحَلْ لَا تُقيِمَنَّ عِنْدَنَا وَاِلاَّ فَكُنْ فِى السِّرِّ والْجَهْرِ مُسْلِماً\" شعرى كبی.\nنكتە: \"لَا تُقيِمَنَّ\" جملەسی \"اِرْحَلْ\" جملەسندن بدل اشتمال اولمقلە كمال اتصال اولوب فصل اولمشدر.\n٣- عطف بيان اولدیغنە مثال : \"فَوَسْوَسَ اِلَيْهِ الشَّيْطَانُ قَالَ يَا آدَمُ هَلْ أَدُلُّكَ عَلَى شَجَرَةِ الْخُلْدِ وَ مُلْكٍ لَا يَبْلَى\" آيت كريمەسى كبى.\nمحل استشهاد: \"قَالَ يَا آدَمُ\" جملەسی\"فَوَسْوَسَ اِلَيْهِ الشَّيْطَانُ\" جملەسندن عطف بيان اولمقلە كمال اتصال اولوب فصل اولمشدر.",
