    "answer_tr": "شبه كمالِ انقطاع: ايكنجى جملەنك برنجى جمله اوزرینە عطف اولونماسی، غیریسی اوزرینە عطفنی ایهام ایتمەسیدر.\nمثلا: \"وَ تَظُنُّ سَلْمَى أَنَّنِى أَبْغِى بِهَا بَدَلًا أُرَاهَا فِى الضَّلَالِ تَهِيمُ\" شعرى كبى.\nنكتە: \"أُرَاهَا\" جملەسی \"تَظُنُّ سَلْمَى\" اوزرينە عطف ایدیلمش اولسە \"أَبْغِى\" جملەسی اوزەرینە عطفنی ایهام ایدەجكی ايچون، شبه كمال انقطاع اولوب فصل اولمشدر.\nشبه كمالِ اتصال؛ ايكنجى جمله برنجى جملەنك اقتضا ايتديكى سؤاله جواب واقع اولماسیدر بوكا \"استیناف\"دە دینیر.",
