    "question_tr": "125- استيناف قاچ قسمدر؟ و بر مثال ویریكز.",
    "answer_tr": "استيناف اوچ قسمدر:\n١- حكمك مطلق سببندن سؤال اولنور؛\nمثلا: \"قَالَ لِى كَيْفَ اَنْتَ قُلْتُ عَلِيلٌ\" شعرى كبى.\nنكتە: استيناف حكمك مطلق سببندن سؤال اولمشدر.\n٢- حكمك خصوصى سببندن سؤال اولنور؛ مثلا: \"وَمَا أُبَرِّئُ نَفْسِى اِنَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ\" آیت كریمەسی كبى\nنكتە: استيناف حكمك خصوصى سببندن سؤال اولمشدر.\n٣- بونلرك غيريسندن سؤال اولنور؛ مثلا: \"قَالُوا سَلاَمًا قَالَ سَلاَمٌ\" آیت كریمەسی كبى\nمحل استشهاد : استيناف حكمك مطلق و خصوصی سببك غیريسندن سؤال اولمشدر.\nمثلا: \"زَعَمَ الْعَواَذِلُ اَنَّنىِ فىِ غَمْرَةٍ - صَدَقُوا وَلكِنْ غَمْرَتِى لاتَنْجَلِى\" شعرى كبی\nنكتە: استيناف حكمك مطلق و خصوصی سببنك غیريسندن سؤال اولمشدر.",
