    "answer_tr": "دواعى وصل ايكى قسمدر:\n١- كمال انقطاع مع الايهام؛\nعطفك ترك ایدیلمەسی، مخاطبە مقصودك خلافنی ایهام ایتمەسیدر. مثلا: \"لاَ وَ اَيَّدَكَ اللهُ\" كبى.\n٢- توسُّط بين الكمالَيْن؛\nایكی جملەنك جهة جامعە ایلە برابر لفظا و معنا ویا سادەجە معنا اخباری و انشائیلكدە اتّفاق ایتمەسیدر.\nمثال:\" يُخَادِعُونَ اللهَ وَهُوَ خَادِعُهُمْ\" آیت كریمەسی كبى\nمحل استشهاد: \"يُخَادِعُونَ اللهَ\" ایلە \"هُوَ خَادِعُهُمْ\" جملەلری آراسندە توسُّط بین الكمالَيْن اولوب وصل اولمشدر.\nمثال:\" اِنَّ الْأَبْرَارَ لَفِى نَعِيمٍ وَ اِنَّ الْفُجَّارَ لَفِى جَحِيمٍ\" آیت كریمەسی كبى\nمحل استشهاد: \" اِنَّ الْأَبْرَارَ لَفِى نَعِيمٍ \" ایلە \" اِنَّ الْفُجَّارَ لَفِى جَحِيمٍ\" جملەلری آراسندە توسُّط بین الكمالَيْن اولوب وصل اولمشدر.\nمثال:\" كُلُوا وَاشْرَبوُا وَلاَ تُسْرِفُوا\" آیت كریمەسی كبى\nمحل استشهاد: \"كُلُوا وَاشْرَبوُا وَلاَ تُسْرِفُوا\" جملەلری آراسندە توسُّط بین الكمالَيْن اولوب وصل اولمشدر.",
