    "answer_tr": "\"وَالْعَیْشُ خَیْرٌ فِی ظِلَالِ النُّوكِ مِمَّنْ عَاشَ كَدَّا\"\nنكتە: اصل مرادى افاده ايتمەيه كافى اولماديغندن اخلال اولدیغی ایچون ايجاز يوقدر.\n\"وَ اَلْفَی قَوْلَهَا كَذِبًا وَ مَیْنًا\"\nنكتە: \"كَذِبًا\" و \"مَيْنًا\" لفظلرى عينى معنايه اولديغی ايچون، تطويل اولدیغی ایچون اطناب يوقدر.\n\"وَلَا فَضْلَ فِیهَا لِلشَّجَاعَةِ وَالنَّدَی وَ صَبْرِ الْفَتَی لَوْلَا لِقَاءُ شَعُوبٍ\"\nنكتە: \"الندى\" كلمەسنده حَشْوِ مُفسِد اولدیغی ایچون اطناب يوقدر.\n\"وَ اَعْلَمُ عِلْمَ الْیَوْمِ وَالْاَمْسِ قَبْلَهُ\"\nنكتە: خشوِ غیرِ مُفسِد اولدیغی ایچون اطناب يوقدر.",
