    "answer_id": "Nuktah dan rahasia balaghahnya adalah: \"وَالْعَیْشُ خَیْرٌ فِی ظِلَالِ النُّوكِ مِمَّنْ عَاشَ كَدَّا\" نكتە: اصل مرادى افاده ايتمەيه كافى اولماديغندن اخلال اولدیغی ایچون ايجاز يوقدر. \"وَ اَلْفَی قَوْلَهَا كَذِبًا وَ مَیْنًا\" نكتە: \"كَذِبًا\" و \"مَيْنًا\" لفظلرى عينى معنايه اولديغی ايچون، تطويل اولدیغی ایچون اطناب يوقدر. \"وَلَا فَضْلَ فِیهَا لِلشَّجَاعَةِ وَالنَّدَی وَ صَبْرِ الْفَتَی لَوْلَا لِقَاءُ شَعُوبٍ\" نكتە: \"الندى\" كلمەسنده حَشْوِ مُفسِد اولدیغی ایچون اطناب يوقدر. \"وَ اَعْلَمُ عِلْمَ الْیَوْمِ وَالْاَمْسِ قَبْلَهُ\" نكتە: خشوِ غیرِ مُفسِد اولدیغی ایچون اطناب يوقدر.",
