    "answer_tr": "\"وَاسْئَلِ الْقَرْیَةَ\"\nمحل استشهاد: جملەنك مضاف جزئی اولان \"اَهْلَ\" كلمەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"وَ كَانَ وَرَائَهُمْ مَلِكٌ يَأْخُذُ كُلَّ سَفینَةٍ غَصْبًا\"\nمحل استشهاد: جملەنك صفت جزئ اولان \"صَحِيحَةٍ\" كلمەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"وَ اِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ اَيْدِيكُمْ وَ مَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ\"\nمحل استشهاد: مجرد اختصار ايچون، جملەنك شرطە جواب اولان جزئی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"وَلَوْ تَرَى اِذْ وُقِفُوا عَلَى النَّارِ\"\nمحل استشهاد: جملەنك جزئی اولان شرطك جوابی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"لَا يَسْتَوِى مِنْكُمْ مَنْ اَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَ قَاتَلَ\"\nمحل استشهاد: جملەنك عطف حرفی ایلە برابر معطوف جزئی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.",
    "question_id": "Jelaskan persoalan balaghah mengenai: ﴿ وَاسْئَلِ الْقَرْیَةَ ﴾ ، ﴿ وَ كَانَ وَرَائَهُمْ ...... ﴾ ، ﴿ وَ اِذَا قِيلَ لَهُمُ اتَّقُوا ....... ﴾ ، ﴿ وَلَوْ تَرَى اِذْ وُقِفُوا ..... ﴾ و ﴿ لَا يَسْتَوِى مِنْكُمْ ..... ﴾ آیت كریمەلرندن بر طانەسنی اوقویوب و محل استشهادینی سویلەیكز.",
    "answer_id": "Penjelasan menurut naskah Talkhis al-Miftah: \"وَاسْئَلِ الْقَرْیَةَ\" محل استشهاد: جملەنك مضاف جزئی اولان \"اَهْلَ\" كلمەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر. \"وَ كَانَ وَرَائَهُمْ مَلِكٌ يَأْخُذُ كُلَّ سَفینَةٍ غَصْبًا\" محل استشهاد: جملەنك صفت جزئ اولان \"صَحِيحَةٍ\" كلمەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر. \"وَ اِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ اَيْدِيكُمْ وَ مَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ\" محل استشهاد: مجرد اختصار ايچون، جملەنك شرطە جواب اولان جزئی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر. \"وَلَوْ تَرَى اِذْ وُقِفُوا عَلَى النَّارِ\" محل استشهاد: جملەنك جزئی اولان شرطك جوابی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر. \"لَا يَسْتَوِى مِنْكُمْ مَنْ اَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَ قَاتَلَ\" محل استشهاد: جملەنك عطف حرفی ایلە برابر معطوف جزئی حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.",
