    "answer_tr": "\"لِيُحِقَّ الْحَقَّ وَ يُبْطِلَ الْبَاطِلَ\"\nمحل استشهاد: مسبَّب اولان \"فَعَلَ مَا فَعَلَ\" جملەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"فَانْفَجَرَتْ\"\nمحل استشهاد: سبب اولان \"فَضَرَبَهُ بِهَا\" جملەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"فَنِعْمَ الْمَاهِدُونَ\"\nمحل استشهاد: مبتدا ایلە برابر مخصوص اولان \"هُمْ نَحْنُ\" جملەسنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.\n\"اَنَا اُنَبِّئُكُمْ بِتَأْوِيلِهِ فَأَرْسِلُونِ يُوسُفُ\"\nمحل استشهاد: بردن چوق جملەنك حذف ایدیلمەسی ایلە ایجازِ حذف اولمشدر.",
