    "question_tr": "135- ايجاز حذفده حذف قاچ وجه اوزره اولور مثاللری ایلە برابر سویلەیكز.",
    "answer_tr": "ایكی وجه اوزرينەدر؛\n١- یا محذوف مقامنە بر شی قائم اولور.\nمثال: \"وَ اِنْ يُكَذِّبوُكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ\" آیت كریمەسی كبی\nمحل استشهاد: محذوف اولان \"فَلَا تَحْزَنْ وَاصْبِرْ\" مقامنە \"فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ\" قائم اولمشدر.\n2- ویا محذوف مقامنە بر شی قائم اولماز.\nمثال: \"فَنِعْمَ الْمَاهِدُونَ\" آیت كریمەسی كبی",
    "question_id": "Ada berapa pembagian dan macam dari ايجاز حذفده حذف قاچ وجه اوزره اولور مثاللری ایلە برابر سویلەیكز.?",
    "answer_id": "Pembagian ايجاز حذفده حذف قاچ وجه اوزره اولور مثاللری ایلە برابر سویلەیكز. menurut kaidah Talkhis al-Miftah adalah: ایكی وجه اوزرينەدر؛ ١- یا محذوف مقامنە بر شی قائم اولور. مثال: \"وَ اِنْ يُكَذِّبوُكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ\" آیت كریمەسی كبی محل استشهاد: محذوف اولان \"فَلَا تَحْزَنْ وَاصْبِرْ\" مقامنە \"فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ\" قائم اولمشدر. 2- ویا محذوف مقامنە بر شی قائم اولماز. مثال: \"فَنِعْمَ الْمَاهِدُونَ\" آیت كریمەسی كبی",
