    "answer_tr": "اطناب يوللرى؛\nا- ابهامدن صكره ايضاح،\n٢- عامدن صكره خاصك ذكرى،\n٣- تكرار،\n٤- ايغال؛ كنديسى اولمادن ده معنانك آكلاشیلابیلەجكی بر شی ایلە بیتی بیتیرمك در.\n٥- تذييل؛ برنجی جملەیی تأكيد ايچون، معناسنه شامل اولان ايكنجى بر جملە ایلە تعقيب ايدیلمەسيدر.\nا- ضربِ مثل منزلەسنه چيقاريلميان،\nب- ضربِ مثل منزلەسنه چيقاريلان،\n٦- تكميل،\n٧- تتميم؛ مقصودك خلافنى ایهام ایتمەین (عقلە كترمەين) بر كلامده بر نكتەدن طولایی فضلەنك كتيريلمسيدر.\n٨- اعتراض؛ بر كلام ويا معنًا متصل اولان ايكى كلام آراسنە اعرابدن محلی اولمایان بر ویا بردن فضلە جملەنك كتیریلمەسیدر.\n٩- بونلرك غيريسى،",
